const buffer = $input.first().json.buffer ?? [];

const text = $('Edit Fields').first().json.text ?? '';
const original = $('Edit Fields').first().json.original ?? null;

// Se original existir, usa ele.
// Senão, usa text.
const textoComparacao =
  original !== null && original !== ''
    ? original
    : text;

// Último elemento do buffer
const ultimaMsg = buffer.length > 0
  ? buffer[buffer.length - 1]
  : null;

// Compara
const status = ultimaMsg === textoComparacao;

return [
  {
    json: {
      status,
      ultimaMsg,
      text: textoComparacao,
      original,
      buffer,
    }
  }
];

const entrada = $input.first()?.json ?? {};
const bufferRaw = entrada.buffer ?? [];
const buffer = Array.isArray(bufferRaw) ? bufferRaw : [bufferRaw];

const mensagemAtual = String(
  $('Edit Fields1').first().json.msg ?? ''
).trim();

// O Redis guarda a mais nova primeiro: inverte para ficar na ordem em que chegaram.
const linhas = buffer
  .map((item) => {
    if (typeof item === 'string') return item.trim();
    return String(item?.text ?? item?.msg ?? item?.content ?? '').trim();
  })
  .filter(Boolean)
  .reverse();

// A mensagem atual já costuma estar no buffer: só acrescenta se ainda não estiver.
if (mensagemAtual && !linhas.includes(mensagemAtual)) linhas.push(mensagemAtual);

const mensage = linhas.join('\n');

return [{ json: { mensage } }];

const base = $('Edit Fields4').first().json;

return [
  {
    json: {
      name: base.name,
      phone: base.phone,
      mensage: base.mensage,
    },
  },
];
